}
#endif

            size_t descLen = StringSize(&data[2 + mimeLen], encoding);
            if (size < 2 ||
                    size - 2 < mimeLen ||
                    size - 2 - mimeLen < descLen) {
                ALOGW("bogus album art sizes");
return NULL;
}
            *length = size - 2 - mimeLen - descLen;

            return &data[2 + mimeLen + descLen];
} else {
